1	import { useEffect, useState } from 'react';
2	import { supabase } from '@/integrations/supabase/client';
3	import {
4	  Dialog,
5	  DialogContent,
6	  DialogDescription,
7	  DialogHeader,
8	  DialogTitle,
9	} from '@/shared/ui/dialog';
10	import {
11	  Loader2,
12	  AlertCircle,
13	  CheckCircle2,
14	  QrCode,
15	  Package,
16	  Truck,
17	  CheckSquare,
18	  MapPin,
19	  Clock,
20	} from 'lucide-react';
21	import { MetroLineNode } from '@/features/logistica/ui/MetroLineNode';
22	import {
23	  Shipment,
24	  ShipmentStatus,
25	  Stop,
26	  RequisicaoSimple,
27	} from '@/shared/types/logistics';
28	import { ScrollArea } from '@/shared/ui/scroll-area';
29	import { generateStops } from '@/shared/lib/logistics-utils';
30	import { Button } from '@/shared/ui/button';
31	import { Separator } from '@/shared/ui/separator';
32	import { Badge } from '@/shared/ui/badge';
33	import { toast } from 'sonner';
34	import { ReceiptScanner } from './ReceiptScanner';
35	import { useAuth } from '@/shared/hooks/useAuth';
36	import { useStore } from '@/shared/contexts/StoreContext';
37	import { cn } from '@/shared/lib/utils';
38	import { handleError } from '@/shared/lib/error-handler';
39	import { wideDebug } from '@/shared/lib/telemetry/wide-events';
40	import { parseQrData } from '@/shared/hooks/useEtiquetaScanner';
41	
42	interface Props {
43	  isOpen: boolean;
44	  onClose: () => void;
45	  expeditionId: string;
46	  storeName: string;
47	}
48	
49	interface ItemReceipt {
50	  id: number;
51	  name: string;
52	  requested: number;
53	  sent: string; // Quantity sent
54	  category: string;
55	  received: boolean; // Local state for checked/scanned
56	  received_at?: string;
57	}
58	
59	export function StoreExpeditionTracker({
60	  isOpen,
61	  onClose,
62	  expeditionId,
63	  storeName,
64	}: Props) {
65	  const { userProfile } = useAuth();
66	  const { selectedStore } = useStore();
67	  const [loading, setLoading] = useState(false);
68	  const [stops, setStops] = useState<Stop[]>([]);
69	  const [shipment, setShipment] = useState<Partial<Shipment> | null>(null);
70	  const [storeItems, setStoreItems] = useState<ItemReceipt[]>([]);
71	  const [isAtDestination, setIsAtDestination] = useState(false);
72	  const [arrivalConfirmed, setArrivalConfirmed] = useState(false);
73	  const [departureConfirmed, setDepartureConfirmed] = useState(false);
74	  const [timeLeftToDepart, setTimeLeftToDepart] = useState<number>(0);
75	  const [isMyTurnToReceive, setIsMyTurnToReceive] = useState(false);
76	
77	  // Scanner State
78	  const [showScanner, setShowScanner] = useState(false);
79	
80	  // Helper to normalize store names for comparison
81	  const normalizeStore = (name: string) => {
82	    return name
83	      .toLowerCase()
84	      .normalize('NFD')
85	      .replace(/[\u0300-\u036f]/g, '') // Remove accents
86	      .replace(/loja\s+/g, '') // Remove 'loja' prefix
87	      .trim();
88	  };
89	
90	  useEffect(() => {
91	    if (!isOpen || !expeditionId) return;
92	
93	    const fetchExpedition = async () => {
94	      setLoading(true);
95	      try {
96	        // Get Expedition (including metadata with route_order)
97	        const { data: exp, error } = await supabase
98	          .from('expedicoes')
99	          .select('*')
100	          .eq('id', expeditionId)
101	          .single();
102	        if (error || !exp) throw new Error('Expedição não encontrada');
103	
104	        // Extract route order from expedition metadata
105	        const routeOrder: string[] = exp.metadata?.route_order || [];
106	
107	        // Get Linked Requisitions (may be empty if new expedition)
108	        const { data: linkedReqs, error: reqError } = await supabase
109	          .from('requisicoes')
110	          .select(
111	            'id, loja_solicitante, data_recebimento, created_at, status, requisicoes_itens(id, nome_produto, quantidade_solicitada, quantidade_enviada, category)',
112	          )
113	          .eq('expedicao_id', exp.id);
114	
115	        if (reqError) {
116	          handleError(reqError, { domain: 'logistica', operation: 'fetchRequisicoes', showToast: false });
117	          toast.error('Erro ao carregar dados da expedição');
118	        }
119	
120	        // Use empty array if no requisitions (expedition may be newly created)
121	        const safeLinkedReqs = linkedReqs || [];
122	
123	        const mappedReqs: RequisicaoSimple[] = safeLinkedReqs.map((r: any) => ({
124	          id: r.id,
125	          loja_solicitante: r.loja_solicitante,
126	          data_recebimento: r.data_recebimento,
127	          created_at: r.created_at,
128	          status: r.status,
129	          item_count: r.requisicoes_itens?.length || 0,
130	        }));
131	
132	        setShipment({
133	          id: exp.id,
134	          status: exp.status as ShipmentStatus,
135	          vehicle: exp.veiculo,
136	          code: exp.code,
137	        });
138	
139	        // Get Logs for Status Calculation
140	        const { data: logs } = await supabase
141	          .from('expedicao_logs')
142	          .select('*')
143	          .eq('expedicao_id', exp.id); // Fetch all logs for this expedition
144	
145	        // Check for arrival/departure confirmation for THIS store
146	        const myStoreLogs =
147	          logs?.filter((l: any) =>
148	            normalizeStore(l.metadata?.store_name || '').includes(
149	              normalizeStore(storeName),
150	            ),
151	          ) || [];
152	        const hasArrival = myStoreLogs.some(
153	          (l: any) => l.type === 'arrival_confirmation',
154	        );
155	        const hasDeparture = myStoreLogs.some(
156	          (l: any) => l.type === 'departure_confirmation',
157	        );
158	
159	        setArrivalConfirmed(hasArrival);
160	        setDepartureConfirmed(hasDeparture);
161	
162	        // Calculate Time Left for Departure (3 minutes delay)
163	        if (hasArrival && !hasDeparture) {
164	          const arrivalLog = logs?.find(
165	            (l: any) =>
166	              l.type === 'arrival_confirmation' &&
167	              normalizeStore(l.metadata?.store_name || '').includes(
168	                normalizeStore(storeName),
169	              ),
170	          );
171	
172	          if (arrivalLog) {
173	            const arrivalTime = new Date(arrivalLog.timestamp).getTime();
174	            const now = new Date().getTime();
175	            const diff = now - arrivalTime;
176	            const threeMinutes = 3 * 60 * 1000;
177	
178	            if (diff < threeMinutes) {
179	              setTimeLeftToDepart(threeMinutes - diff);
180	            } else {
181	              setTimeLeftToDepart(0);
182	            }
183	          }
184	        } else if (hasDeparture) {
185	          setTimeLeftToDepart(0);
186	        }
187	
188	        // Generate FULL Steps with route order from expedition configuration
189	        const allStops = generateStops(
190	          mappedReqs,
191	          exp.status as ShipmentStatus,
192	          (logs || []) as any,
193	          routeOrder,
194	        );
195	
196	        // Find store in the configured route order
197	        let myStorePosition = -1;
198	        if (routeOrder.length > 0) {
199	          myStorePosition = routeOrder.findIndex(
200	            (storeInRoute) =>
201	              normalizeStore(storeInRoute).includes(
202	                normalizeStore(storeName),
203	              ) ||
204	              normalizeStore(storeName).includes(normalizeStore(storeInRoute)),
205	          );
206	        }
207	
208	        // Fallback: find in generated stops
209	        const myStopIndex = allStops.findIndex(
210	          (s) =>
211	            s.type === 'store' &&
212	            (normalizeStore(s.name).includes(normalizeStore(storeName)) ||
213	              normalizeStore(storeName).includes(
214	                normalizeStore(s.name.replace('Loja ', '')),
215	              )),
216	        );
217	
218	        // Determine logic for "Is My Turn"
219	        // It is my turn if:
220	        // 1. Expedition is dispatched (past loading)
221	        // 2. Previous store is completed (or I am the first store)
222	        let isTurn = false;
223	        const expeditionDispatched = [
224	          'dispatch',
225	          'in_transit',
226	          'unloading',
227	        ].includes(exp.status);
228	
229	        if (expeditionDispatched && myStopIndex !== -1) {
230	          // Check previous stop
231	          if (myStopIndex === 0) {
232	            // Impossible for store to be index 0 (always processes before), but defensive check
233	            isTurn = true;
234	          } else {
235	            // Find the store stop immediately preceding mine (ignoring processes if any mixed in, though usually processes come first)
236	            // Actually, we check the immediate previous stop in the timeline
237	            const prevStop = allStops[myStopIndex - 1];
238	            // If prev stop is 'completed', then it's my turn
239	            // Or if prev stop is 'current' but I am also 'current' (should not happen in sequence but logically)
240	            // But simplify: My turn if previous is completed.
241	            if (prevStop.status === 'completed') {
242	              isTurn = true;
243	            }
244	          }
245	        }
246	
247	        // If I already confirmed arrival, it's definitely my turn (or past my turn)
248	        if (hasArrival) isTurn = true;
249	
250	        setIsMyTurnToReceive(isTurn);
251	
252	        // Determine if this is the last store in the route
253	        const isLastStoreInRoute =
254	          routeOrder.length > 0
255	            ? myStorePosition === routeOrder.length - 1
256	            : myStopIndex ===
257	              allStops.filter((s) => s.type === 'store').length - 1 + 3; // +3 for process steps
258	
259	        // Show timeline up to my store (or all if last store)
260	        if (myStopIndex !== -1) {
261	          if (isLastStoreInRoute) {
262	            // Last store in route sees the complete timeline
263	            setStops(allStops);
264	          } else {
265	            // Other stores see timeline only up to their position
266	            setStops(allStops.slice(0, myStopIndex + 1));
267	          }
268	          setIsAtDestination(true);
269	
270	          // Filter items for THIS store
271	          const myReqs = safeLinkedReqs.filter(
272	            (r: any) =>
273	              normalizeStore(r.loja_solicitante) ===
274	                normalizeStore(storeName) ||
275	              normalizeStore(r.loja_solicitante).includes(
276	                normalizeStore(storeName),
277	              ) ||
278	              normalizeStore(storeName).includes(
279	                normalizeStore(r.loja_solicitante),
280	              ),
281	          );
282	
283	          const items: ItemReceipt[] = [];
284	          myReqs.forEach((r: any) => {
285	            if (r.requisicoes_itens) {
286	              r.requisicoes_itens.forEach((i: any) => {
287	                // Skip if not sent (quantity_sent is empty or zero)
288	                if (!i.quantidade_enviada || i.quantidade_enviada === '0')
289	                  return;
290	
291	                items.push({
292	                  id: i.id,
293	                  name: i.nome_produto,
294	                  requested: i.quantidade_solicitada,
295	                  sent: i.quantidade_enviada,
296	                  category: i.category || 'Geral',
297	                  received: !!i.received_at, // If field exists and is set
298	                  received_at: i.received_at,
299	                });
300	              });
301	            }
302	          });
303	          setStoreItems(items);
304	        } else {
305	          // Store not found directly - show ALL stops so manager can still track
306	          setStops(allStops);
307	          setIsAtDestination(false);
308	          setStoreItems([]);
309	        }
310	      } catch (err) {
311	        handleError(err, { domain: 'logistica', operation: 'fetchExpedition', showToast: false });
312	        setStops([]);
313	      } finally {
314	        setLoading(false);
315	      }
316	    };
317	
318	    fetchExpedition();
319	
320	    // Timer Interval
321	    const interval = setInterval(() => {
322	      setTimeLeftToDepart((prev) => {
323	        if (prev <= 0) return 0;
324	        return Math.max(0, prev - 1000);
325	      });
326	    }, 1000);
327	
328	    return () => clearInterval(interval);
329	  }, [isOpen, expeditionId, storeName]);
330	
331	  const handleConfirmArrival = async () => {
332	    if (!shipment?.id) return;
333	
334	    try {
335	      const userName = userProfile?.nome || 'Gerente';
336	
337	      // Log arrival
338	      await supabase.from('expedicao_logs').insert({
339	        expedicao_id: shipment.id,
340	        title: 'Chegada Confirmada',
341	        description: `O caminhão chegou na loja ${storeName}.`,
342	        type: 'arrival_confirmation',
343	        user_name: userName,
344	        metadata: { store_name: storeName },
345	      });
346	
347	      setArrivalConfirmed(true);
348	      toast.success('Chegada do caminhão confirmada!');
349	    } catch (error) {
350	      handleError(error, { domain: 'logistica', operation: 'confirmArrival', showToast: false });
351	      toast.error('Erro ao confirmar chegada.');
352	    }
353	  };
354	
355	  const handleConfirmDeparture = async () => {
356	    if (!shipment?.id) return;
357	
358	    if (!confirm('Confirmar que o caminhão já partiu para a próxima etapa?'))
359	      return;
360	
361	    try {
362	      const userName = userProfile?.nome || 'Gerente';
363	
364	      // Log departure
365	      await supabase.from('expedicao_logs').insert({
366	        expedicao_id: shipment.id,
367	        title: 'Saída Confirmada',
368	        description: `O caminhão partiu da loja ${storeName}.`,
369	        type: 'departure_confirmation',
370	        user_name: userName,
371	        metadata: { store_name: storeName },
372	      });
373	
374	      setDepartureConfirmed(true);
375	      toast.success('Partida confirmada!');
376	      onClose(); // Optional: close modal as job is done
377	    } catch (error) {
378	      handleError(error, { domain: 'logistica', operation: 'confirmDeparture', showToast: false });
379	      toast.error('Erro ao confirmar partida.');
380	    }
381	  };
382	
383	  const handleScan = async (scannedCode: string) => {
384	    wideDebug('logistica.scan.received', 'Código escaneado recebido', { domain: 'logistica', attributes: { scannedCode } });
385	
386	    // Caminho 1: QR estruturado da Momma (etiqueta_qr) — bip RPC + INSERT
387	    // movimentação tipo='entrada' com etiqueta_qr_uid. Trigger sobe estoque.
388	    const payload = parseQrData(scannedCode);
389	    if (payload?.uid) {
390	      const lojaDestinoId = selectedStore?.id ?? null;
391	      if (!lojaDestinoId) {
392	        toast.error('Loja destino não identificada — selecione uma loja antes de bipar.');
393	        return;
394	      }
395	
396	      // RPC central
397	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
398	      const { data: rpcRaw, error: rpcErr } = await (supabase.rpc as any)('bipar_etiqueta', {
399	        p_uid: payload.uid,
400	        p_etapa: 'entrada',
401	        p_contexto: {
402	          loja_id: lojaDestinoId,
403	          referencia_tipo: 'expedicao',
404	          referencia_id: shipment?.id ? String(shipment.id) : null,
405	          payload,
406	        },
407	      });
408	      const rpc = rpcRaw as {
409	        ok: boolean;
410	        erro?: string;
411	        etiqueta?: {
412	          produto_master_id: number;
413	          produto_nome_snapshot?: string | null;
414	          lote_id?: string | null;
415	          quantidade_interna?: number;
416	        };
417	        alertas?: string[];
418	      } | null;
419	      if (rpcErr || !rpc?.ok || !rpc.etiqueta) {
420	        toast.error(rpc?.erro || rpcErr?.message || 'Bip rejeitado');
421	        return;
422	      }
423	      (rpc.alertas ?? []).forEach((a) => toast.warning(a));
424	
425	      const et = rpc.etiqueta;
426	      const qty = Number(et.quantidade_interna || 1);
427	
428	      // INSERT movimentação — trigger atualizar_estoque_e_alertas sobe saldo
429	      const { data: estoqueAtual } = await supabase
430	        .from('estoque')
431	        .select('quantidade_atual')
432	        .eq('produto_master_id', et.produto_master_id)
433	        .eq('loja_id', lojaDestinoId)
434	        .maybeSingle();
435	      const anterior = (estoqueAtual as { quantidade_atual?: number } | null)?.quantidade_atual ?? 0;
436	      const nova = anterior + qty;
437	
438	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
439	      const { error: movErr } = await (supabase.from('movimentacoes') as any).insert({
440	        produto_master_id: et.produto_master_id,
441	        tipo_movimentacao: 'entrada',
442	        quantidade: qty,
443	        quantidade_anterior: anterior,
444	        quantidade_nova: nova,
445	        motivo: 'recebimento',
446	        observacoes: `Recebimento via expedição ${shipment?.id ?? ''} — UID ${payload.uid}`,
447	        data_movimentacao: new Date().toISOString(),
448	        loja_id: lojaDestinoId,
449	        lote_id: et.lote_id || null,
450	        etiqueta_qr_uid: payload.uid,
451	      });
452	      if (movErr) {
453	        toast.error(`Erro ao registrar entrada no estoque: ${movErr.message}`);
454	        return;
455	      }
456	
457	      // Marca item da requisição como recebido (se houver match por produto_master)
458	      const matchedItem = storeItems.find(
459	        (i) => !i.received && (i.name?.toLowerCase().includes((et.produto_nome_snapshot || '').toLowerCase())),
460	      );
461	      if (matchedItem) {
462	        await supabase
463	          .from('requisicoes_itens')
464	          // eslint-disable-next-line @typescript-eslint/no-explicit-any
465	          .update({ received_at: new Date().toISOString() } as any)
466	          .eq('id', matchedItem.id);
467	        setStoreItems((prev) => prev.map((i) => (i.id === matchedItem.id ? { ...i, received: true } : i)));
468	      }
469	
470	      toast.success(`Recebido: ${et.produto_nome_snapshot || `Produto #${et.produto_master_id}`} (+${qty})`);
471	      return;
472	    }
473	
474	    // Caminho 2: QR não-estruturado (fallback legado) — match por id/nome do item
475	    const matchedItem = storeItems.find(
476	      (i) =>
477	        scannedCode.includes(`pid:${i.id}`) ||
478	        scannedCode === String(i.id) ||
479	        (i.name && scannedCode.toLowerCase().includes(i.name.toLowerCase())),
480	    );
481	
482	    if (!matchedItem) {
483	      toast.warning('Item não encontrado nesta expedição para sua loja.');
484	      return;
485	    }
486	    if (matchedItem.received) {
487	      toast.info(`Item "${matchedItem.name}" já foi recebido.`);
488	      return;
489	    }
490	
491	    const { error } = await supabase
492	      .from('requisicoes_itens')
493	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
494	      .update({ received_at: new Date().toISOString() } as any)
495	      .eq('id', matchedItem.id);
496	
497	    if (!error) {
498	      setStoreItems((prev) => prev.map((i) => (i.id === matchedItem.id ? { ...i, received: true } : i)));
499	      toast.success(`Recebido: ${matchedItem.name}`);
500	    } else {
501	      await supabase.from('expedicao_logs').insert({
502	        expedicao_id: shipment?.id,
503	        title: 'Item Recebido',
504	        description: `Item "${matchedItem.name}" conferido via QR Code.`,
505	        type: 'info',
506	        user_name: userProfile?.nome || 'Sistema',
507	        metadata: { item_id: matchedItem.id, store_name: storeName },
508	      });
509	      setStoreItems((prev) => prev.map((i) => (i.id === matchedItem.id ? { ...i, received: true } : i)));
510	      toast.success(`Recebido: ${matchedItem.name} (Log)`);
511	    }
512	  };
513	
514	  const handleManualCheck = async (item: ItemReceipt) => {
515	    if (item.received) return;
516	
517	    if (!confirm(`Confirmar recebimento manual de "${item.name}"?`)) return;
518	
519	    // Same logic as scan
520	    const { error } = await supabase
521	      .from('requisicoes_itens')
522	      .update({ received_at: new Date().toISOString() } as any)
523	      .eq('id', item.id);
524	
525	    if (!error) {
526	      setStoreItems((prev) =>
527	        prev.map((i) => (i.id === item.id ? { ...i, received: true } : i)),
528	      );
529	      toast.success(`Recebido: ${item.name}`);
530	    } else {
531	      toast.error('Erro ao marcar como recebido.');
532	    }
533	  };
534	
535	  const progress =
536	    storeItems.length > 0
537	      ? Math.round(
538	          (storeItems.filter((i) => i.received).length / storeItems.length) *
539	            100,
540	        )
541	      : 0;
542	
543	  return (
544	    <Dialog open={isOpen} onOpenChange={onClose}>
545	      <DialogContent data-mia-modal="rastreamento-de-expedi-o" className="max-w-4xl w-full max-h-[90vh] flex flex-col bg-slate-50 dark:bg-zinc-900 border-none p-0 overflow-hidden shadow-2xl">
546	        <div className="p-6 pb-2 bg-white/80 dark:bg-zinc-900/80 backdrop-blur-md border-b border-slate-200 dark:border-zinc-800">
547	          <DialogHeader>
548	            <DialogTitle className="text-xl font-bold text-slate-800 dark:text-slate-100 flex items-center gap-2">
549	              Rastreamento de Expedição
550	            </DialogTitle>
551	            <DialogDescription className="text-slate-500 dark:text-slate-400">
552	              Acompanhe o status e realize a conferência.
553	            </DialogDescription>
554	          </DialogHeader>
555	          {shipment && (
556	            <div className="mt-4 flex flex-wrap gap-4 text-xs font-medium text-slate-600 dark:text-slate-300">
557	              <Badge
558	                variant="outline"
559	                className="bg-white/50 dark:bg-zinc-800/50 border-slate-200 dark:border-zinc-700"
560	              >
561	                {shipment.code}
562	              </Badge>
563	              <span className="flex items-center gap-1">
564	                <Truck className="w-3 h-3 text-slate-400" /> {shipment.vehicle}
565	              </span>
566	              <span className="flex items-center gap-1">
567	                <MapPin className="w-3 h-3 text-slate-400" /> {storeName}
568	              </span>
569	            </div>
570	          )}
571	        </div>
572	
573	        <div className="flex-1 overflow-y-auto p-6 md:p-10 space-y-8">
574	          {/* TIMELINE */}
575	          {loading ? (
576	            <div className="flex justify-center p-10">
577	              <Loader2 className="w-10 h-10 text-emerald-600 animate-spin" />
578	            </div>
579	          ) : stops.length === 0 ? (
580	            <div className="flex flex-col items-center text-slate-400 dark:text-slate-500 p-10">
581	              <AlertCircle className="w-10 h-10 mb-2" />
582	              <p>Não foi possível carregar a rota.</p>
583	            </div>
584	          ) : (
