import { useEffect, useState } from 'react';
import { supabase } from '@/integrations/supabase/client';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/shared/ui/dialog';
import {
  Loader2,
  AlertCircle,
  CheckCircle2,
  QrCode,
  Package,
  Truck,
  CheckSquare,
  MapPin,
  Clock,
} from 'lucide-react';
import { MetroLineNode } from '@/features/logistica/ui/MetroLineNode';
import {
  Shipment,
  ShipmentStatus,
  Stop,
  RequisicaoSimple,
} from '@/shared/types/logistics';
import { ScrollArea } from '@/shared/ui/scroll-area';
import { generateStops } from '@/shared/lib/logistics-utils';
import { Button } from '@/shared/ui/button';
import { Separator } from '@/shared/ui/separator';
import { Badge } from '@/shared/ui/badge';
import { toast } from 'sonner';
import { ReceiptScanner } from './ReceiptScanner';
import { useAuth } from '@/shared/hooks/useAuth';
import { useStore } from '@/shared/contexts/StoreContext';
import { cn } from '@/shared/lib/utils';
import { handleError } from '@/shared/lib/error-handler';
import { wideDebug } from '@/shared/lib/telemetry/wide-events';
import { parseQrData } from '@/shared/hooks/useEtiquetaScanner';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  expeditionId: string;
  storeName: string;
}

interface ItemReceipt {
  id: number;
  name: string;
  requested: number;
  sent: string; // Quantity sent
  category: string;
  received: boolean; // Local state for checked/scanned
  received_at?: string;
}

export function StoreExpeditionTracker({
  isOpen,
  onClose,
  expeditionId,
  storeName,
}: Props) {
  const { userProfile } = useAuth();
  const { selectedStore } = useStore();
  const [loading, setLoading] = useState(false);
  const [stops, setStops] = useState<Stop[]>([]);
  const [shipment, setShipment] = useState<Partial<Shipment> | null>(null);
  const [storeItems, setStoreItems] = useState<ItemReceipt[]>([]);
  const [isAtDestination, setIsAtDestination] = useState(false);
  const [arrivalConfirmed, setArrivalConfirmed] = useState(false);
  const [departureConfirmed, setDepartureConfirmed] = useState(false);
  const [timeLeftToDepart, setTimeLeftToDepart] = useState<number>(0);
  const [isMyTurnToReceive, setIsMyTurnToReceive] = useState(false);

  // Scanner State
  const [showScanner, setShowScanner] = useState(false);

  // Helper to normalize store names for comparison
  const normalizeStore = (name: string) => {
    return name
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '') // Remove accents
      .replace(/loja\s+/g, '') // Remove 'loja' prefix
      .trim();
  };

  useEffect(() => {
    if (!isOpen || !expeditionId) return;

    const fetchExpedition = async () => {
      setLoading(true);
      try {
        // Get Expedition (including metadata with route_order)
        const { data: exp, error } = await supabase
          .from('expedicoes')
          .select('*')
          .eq('id', expeditionId)
          .single();
        if (error || !exp) throw new Error('Expedição não encontrada');

        // Extract route order from expedition metadata
        const routeOrder: string[] = exp.metadata?.route_order || [];

        // Get Linked Requisitions (may be empty if new expedition)
        const { data: linkedReqs, error: reqError } = await supabase
          .from('requisicoes')
          .select(
            'id, loja_solicitante, data_recebimento, created_at, status, requisicoes_itens(id, nome_produto, quantidade_solicitada, quantidade_enviada, category)',
          )
          .eq('expedicao_id', exp.id);

        if (reqError) {
          handleError(reqError, { domain: 'logistica', operation: 'fetchRequisicoes', showToast: false });
          toast.error('Erro ao carregar dados da expedição');
        }

        // Use empty array if no requisitions (expedition may be newly created)
        const safeLinkedReqs = linkedReqs || [];

        const mappedReqs: RequisicaoSimple[] = safeLinkedReqs.map((r: any) => ({
          id: r.id,
          loja_solicitante: r.loja_solicitante,
          data_recebimento: r.data_recebimento,
          created_at: r.created_at,
          status: r.status,
          item_count: r.requisicoes_itens?.length || 0,
        }));

        setShipment({
          id: exp.id,
          status: exp.status as ShipmentStatus,
          vehicle: exp.veiculo,
          code: exp.code,
        });

        // Get Logs for Status Calculation
        const { data: logs } = await supabase
          .from('expedicao_logs')
          .select('*')
          .eq('expedicao_id', exp.id); // Fetch all logs for this expedition

        // Check for arrival/departure confirmation for THIS store
        const myStoreLogs =
          logs?.filter((l: any) =>
            normalizeStore(l.metadata?.store_name || '').includes(
              normalizeStore(storeName),
            ),
          ) || [];
        const hasArrival = myStoreLogs.some(
          (l: any) => l.type === 'arrival_confirmation',
        );
        const hasDeparture = myStoreLogs.some(
          (l: any) => l.type === 'departure_confirmation',
        );

        setArrivalConfirmed(hasArrival);
        setDepartureConfirmed(hasDeparture);

        // Calculate Time Left for Departure (3 minutes delay)
        if (hasArrival && !hasDeparture) {
          const arrivalLog = logs?.find(
            (l: any) =>
              l.type === 'arrival_confirmation' &&
              normalizeStore(l.metadata?.store_name || '').includes(
                normalizeStore(storeName),
              ),
          );

          if (arrivalLog) {
            const arrivalTime = new Date(arrivalLog.timestamp).getTime();
            const now = new Date().getTime();
            const diff = now - arrivalTime;
            const threeMinutes = 3 * 60 * 1000;

            if (diff < threeMinutes) {
              setTimeLeftToDepart(threeMinutes - diff);
            } else {
              setTimeLeftToDepart(0);
            }
          }
        } else if (hasDeparture) {
          setTimeLeftToDepart(0);
        }

        // Generate FULL Steps with route order from expedition configuration
        const allStops = generateStops(
          mappedReqs,
          exp.status as ShipmentStatus,
          (logs || []) as any,
          routeOrder,
        );

        // Find store in the configured route order
        let myStorePosition = -1;
        if (routeOrder.length > 0) {
          myStorePosition = routeOrder.findIndex(
            (storeInRoute) =>
              normalizeStore(storeInRoute).includes(
                normalizeStore(storeName),
              ) ||
              normalizeStore(storeName).includes(normalizeStore(storeInRoute)),
          );
        }

        // Fallback: find in generated stops
        const myStopIndex = allStops.findIndex(
          (s) =>
            s.type === 'store' &&
            (normalizeStore(s.name).includes(normalizeStore(storeName)) ||
              normalizeStore(storeName).includes(
                normalizeStore(s.name.replace('Loja ', '')),
              )),
        );

        // Determine logic for "Is My Turn"
        // It is my turn if:
        // 1. Expedition is dispatched (past loading)
        // 2. Previous store is completed (or I am the first store)
        let isTurn = false;
        const expeditionDispatched = [
          'dispatch',
          'in_transit',
          'unloading',
        ].includes(exp.status);

        if (expeditionDispatched && myStopIndex !== -1) {
          // Check previous stop
          if (myStopIndex === 0) {
            // Impossible for store to be index 0 (always processes before), but defensive check
            isTurn = true;
          } else {
            // Find the store stop immediately preceding mine (ignoring processes if any mixed in, though usually processes come first)
            // Actually, we check the immediate previous stop in the timeline
            const prevStop = allStops[myStopIndex - 1];
            // If prev stop is 'completed', then it's my turn
            // Or if prev stop is 'current' but I am also 'current' (should not happen in sequence but logically)
            // But simplify: My turn if previous is completed.
            if (prevStop.status === 'completed') {
              isTurn = true;
            }
          }
        }

        // If I already confirmed arrival, it's definitely my turn (or past my turn)
        if (hasArrival) isTurn = true;

        setIsMyTurnToReceive(isTurn);

        // Determine if this is the last store in the route
        const isLastStoreInRoute =
          routeOrder.length > 0
            ? myStorePosition === routeOrder.length - 1
            : myStopIndex ===
              allStops.filter((s) => s.type === 'store').length - 1 + 3; // +3 for process steps

        // Show timeline up to my store (or all if last store)
        if (myStopIndex !== -1) {
          if (isLastStoreInRoute) {
            // Last store in route sees the complete timeline
            setStops(allStops);
          } else {
            // Other stores see timeline only up to their position
            setStops(allStops.slice(0, myStopIndex + 1));
          }
          setIsAtDestination(true);

          // Filter items for THIS store
          const myReqs = safeLinkedReqs.filter(
            (r: any) =>
              normalizeStore(r.loja_solicitante) ===
                normalizeStore(storeName) ||
              normalizeStore(r.loja_solicitante).includes(
                normalizeStore(storeName),
              ) ||
              normalizeStore(storeName).includes(
                normalizeStore(r.loja_solicitante),
              ),
          );

          const items: ItemReceipt[] = [];
          myReqs.forEach((r: any) => {
            if (r.requisicoes_itens) {
              r.requisicoes_itens.forEach((i: any) => {
                // Skip if not sent (quantity_sent is empty or zero)
                if (!i.quantidade_enviada || i.quantidade_enviada === '0')
                  return;

                items.push({
                  id: i.id,
                  name: i.nome_produto,
                  requested: i.quantidade_solicitada,
                  sent: i.quantidade_enviada,
                  category: i.category || 'Geral',
                  received: !!i.received_at, // If field exists and is set
                  received_at: i.received_at,
                });
              });
            }
          });
          setStoreItems(items);
        } else {
          // Store not found directly - show ALL stops so manager can still track
          setStops(allStops);
          setIsAtDestination(false);
          setStoreItems([]);
        }
      } catch (err) {
        handleError(err, { domain: 'logistica', operation: 'fetchExpedition', showToast: false });
        setStops([]);
      } finally {
        setLoading(false);
      }
    };

    fetchExpedition();

    // Timer Interval
    const interval = setInterval(() => {
      setTimeLeftToDepart((prev) => {
        if (prev <= 0) return 0;
        return Math.max(0, prev - 1000);
      });
    }, 1000);

    return () => clearInterval(interval);
  }, [isOpen, expeditionId, storeName]);

  const handleConfirmArrival = async () => {
    if (!shipment?.id) return;

    try {
      const userName = userProfile?.nome || 'Gerente';

      // Log arrival
      await supabase.from('expedicao_logs').insert({
        expedicao_id: shipment.id,
        title: 'Chegada Confirmada',
        description: `O caminhão chegou na loja ${storeName}.`,
        type: 'arrival_confirmation',
        user_name: userName,
        metadata: { store_name: storeName },
      });

      setArrivalConfirmed(true);
      toast.success('Chegada do caminhão confirmada!');
    } catch (error) {
      handleError(error, { domain: 'logistica', operation: 'confirmArrival', showToast: false });
      toast.error('Erro ao confirmar chegada.');
    }
  };

  const handleConfirmDeparture = async () => {
    if (!shipment?.id) return;

    if (!confirm('Confirmar que o caminhão já partiu para a próxima etapa?'))
      return;

    try {
      const userName = userProfile?.nome || 'Gerente';

      // Log departure
      await supabase.from('expedicao_logs').insert({
        expedicao_id: shipment.id,
        title: 'Saída Confirmada',
        description: `O caminhão partiu da loja ${storeName}.`,
        type: 'departure_confirmation',
        user_name: userName,
        metadata: { store_name: storeName },
      });

      setDepartureConfirmed(true);
      toast.success('Partida confirmada!');
      onClose(); // Optional: close modal as job is done
    } catch (error) {
      handleError(error, { domain: 'logistica', operation: 'confirmDeparture', showToast: false });
      toast.error('Erro ao confirmar partida.');
    }
  };

  const handleScan = async (scannedCode: string) => {
    wideDebug('logistica.scan.received', 'Código escaneado recebido', { domain: 'logistica', attributes: { scannedCode } });

    // Caminho 1: QR estruturado da Momma (etiqueta_qr) — bip RPC + INSERT
    // movimentação tipo='entrada' com etiqueta_qr_uid. Trigger sobe estoque.
    const payload = parseQrData(scannedCode);
    if (payload?.uid) {
      const lojaDestinoId = selectedStore?.id ?? null;
      if (!lojaDestinoId) {
        toast.error('Loja destino não identificada — selecione uma loja antes de bipar.');
        return;
      }

      // RPC central
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const { data: rpcRaw, error: rpcErr } = await (supabase.rpc as any)('bipar_etiqueta', {
        p_uid: payload.uid,
        p_etapa: 'entrada',
        p_contexto: {
          loja_id: lojaDestinoId,
          referencia_tipo: 'expedicao',
          referencia_id: shipment?.id ? String(shipment.id) : null,
          payload,
        },
      });
      const rpc = rpcRaw as {
        ok: boolean;
        erro?: string;
        etiqueta?: {
          produto_master_id: number;
          produto_nome_snapshot?: string | null;
          lote_id?: string | null;
          quantidade_interna?: number;
        };
        alertas?: string[];
      } | null;
      if (rpcErr || !rpc?.ok || !rpc.etiqueta) {
        toast.error(rpc?.erro || rpcErr?.message || 'Bip rejeitado');
        return;
      }
      (rpc.alertas ?? []).forEach((a) => toast.warning(a));

      const et = rpc.etiqueta;
      const qty = Number(et.quantidade_interna || 1);

      // INSERT movimentação — trigger atualizar_estoque_e_alertas sobe saldo
      const { data: estoqueAtual } = await supabase
        .from('estoque')
        .select('quantidade_atual')
        .eq('produto_master_id', et.produto_master_id)
        .eq('loja_id', lojaDestinoId)
        .maybeSingle();
      const anterior = (estoqueAtual as { quantidade_atual?: number } | null)?.quantidade_atual ?? 0;
      const nova = anterior + qty;

      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const { error: movErr } = await (supabase.from('movimentacoes') as any).insert({
        produto_master_id: et.produto_master_id,
        tipo_movimentacao: 'entrada',
        quantidade: qty,
        quantidade_anterior: anterior,
        quantidade_nova: nova,
        motivo: 'recebimento',
        observacoes: `Recebimento via expedição ${shipment?.id ?? ''} — UID ${payload.uid}`,
        data_movimentacao: new Date().toISOString(),
        loja_id: lojaDestinoId,
        lote_id: et.lote_id || null,
        etiqueta_qr_uid: payload.uid,
      });
      if (movErr) {
        toast.error(`Erro ao registrar entrada no estoque: ${movErr.message}`);
        return;
      }

      // Marca item da requisição como recebido (se houver match por produto_master)
      const matchedItem = storeItems.find(
        (i) => !i.received && (i.name?.toLowerCase().includes((et.produto_nome_snapshot || '').toLowerCase())),
      );
      if (matchedItem) {
        await supabase
          .from('requisicoes_itens')
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          .update({ received_at: new Date().toISOString() } as any)
          .eq('id', matchedItem.id);
        setStoreItems((prev) => prev.map((i) => (i.id === matchedItem.id ? { ...i, received: true } : i)));
      }

      toast.success(`Recebido: ${et.produto_nome_snapshot || `Produto #${et.produto_master_id}`} (+${qty})`);
      return;
    }

    // Caminho 2: QR não-estruturado (fallback legado) — match por id/nome do item
    const matchedItem = storeItems.find(
      (i) =>
        scannedCode.includes(`pid:${i.id}`) ||
        scannedCode === String(i.id) ||
        (i.name && scannedCode.toLowerCase().includes(i.name.toLowerCase())),
    );

    if (!matchedItem) {
      toast.warning('Item não encontrado nesta expedição para sua loja.');
      return;
    }
    if (matchedItem.received) {
      toast.info(`Item "${matchedItem.name}" já foi recebido.`);
      return;
    }

    const { error } = await supabase
      .from('requisicoes_itens')
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      .update({ received_at: new Date().toISOString() } as any)
      .eq('id', matchedItem.id);

    if (!error) {
      setStoreItems((prev) => prev.map((i) => (i.id === matchedItem.id ? { ...i, received: true } : i)));
      toast.success(`Recebido: ${matchedItem.name}`);
    } else {
      await supabase.from('expedicao_logs').insert({
        expedicao_id: shipment?.id,
        title: 'Item Recebido',
        description: `Item "${matchedItem.name}" conferido via QR Code.`,
        type: 'info',
        user_name: userProfile?.nome || 'Sistema',
        metadata: { item_id: matchedItem.id, store_name: storeName },
      });
      setStoreItems((prev) => prev.map((i) => (i.id === matchedItem.id ? { ...i, received: true } : i)));
      toast.success(`Recebido: ${matchedItem.name} (Log)`);
    }
  };

  const handleManualCheck = async (item: ItemReceipt) => {
    if (item.received) return;

    if (!confirm(`Confirmar recebimento manual de "${item.name}"?`)) return;

    // Same logic as scan
    const { error } = await supabase
      .from('requisicoes_itens')
      .update({ received_at: new Date().toISOString() } as any)
      .eq('id', item.id);

    if (!error) {
      setStoreItems((prev) =>
        prev.map((i) => (i.id === item.id ? { ...i, received: true } : i)),
      );
      toast.success(`Recebido: ${item.name}`);
    } else {
      toast.error('Erro ao marcar como recebido.');
    }
  };

  const progress =
    storeItems.length > 0
      ? Math.round(
          (storeItems.filter((i) => i.received).length / storeItems.length) *
            100,
        )
      : 0;

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent data-mia-modal="rastreamento-de-expedi-o" className="max-w-4xl w-full max-h-[90vh] flex flex-col bg-slate-50 dark:bg-zinc-900 border-none p-0 overflow-hidden shadow-2xl">
        <div className="p-6 pb-2 bg-white/80 dark:bg-zinc-900/80 backdrop-blur-md border-b border-slate-200 dark:border-zinc-800">
          <DialogHeader>
            <DialogTitle className="text-xl font-bold text-slate-800 dark:text-slate-100 flex items-center gap-2">
              Rastreamento de Expedição
            </DialogTitle>
            <DialogDescription className="text-slate-500 dark:text-slate-400">
              Acompanhe o status e realize a conferência.
            </DialogDescription>
          </DialogHeader>
          {shipment && (
            <div className="mt-4 flex flex-wrap gap-4 text-xs font-medium text-slate-600 dark:text-slate-300">
              <Badge
                variant="outline"
                className="bg-white/50 dark:bg-zinc-800/50 border-slate-200 dark:border-zinc-700"
              >
                {shipment.code}
              </Badge>
              <span className="flex items-center gap-1">
                <Truck className="w-3 h-3 text-slate-400" /> {shipment.vehicle}
              </span>
              <span className="flex items-center gap-1">
                <MapPin className="w-3 h-3 text-slate-400" /> {storeName}
              </span>
            </div>
          )}
        </div>

        <div className="flex-1 overflow-y-auto p-6 md:p-10 space-y-8">
          {/* TIMELINE */}
          {loading ? (
            <div className="flex justify-center p-10">
              <Loader2 className="w-10 h-10 text-emerald-600 animate-spin" />
            </div>
          ) : stops.length === 0 ? (
            <div className="flex flex-col items-center text-slate-400 dark:text-slate-500 p-10">
              <AlertCircle className="w-10 h-10 mb-2" />
              <p>Não foi possível carregar a rota.</p>
            </div>
          ) : (
            <div className="overflow-x-auto pb-6">
              <div className="flex items-start gap-0 min-w-max">
                {stops.map((stop, index) => (
                  <MetroLineNode
                    key={stop.id}
                    stop={stop}
                    isFirst={index === 0}
                    isLast={index === stops.length - 1}
                  />
                ))}
              </div>
            </div>
          )}

          {/* CONFIRM ARRIVAL SECTION */}
          {isAtDestination && !loading && (
            <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-700">
              <Separator className="bg-slate-200 dark:bg-zinc-800" />

              <div className="flex flex-col md:flex-row items-center justify-between gap-4 bg-white dark:bg-zinc-800/50 p-6 rounded-2xl border border-slate-200 dark:border-zinc-700 shadow-sm">
                <div>
                  <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100">
                    Sua Entrega
                  </h3>
                  <p className="text-sm text-slate-500 dark:text-slate-400">
                    {departureConfirmed
                      ? 'Entrega finalizada. Caminhão partiu.'
                      : arrivalConfirmed
                        ? 'Caminhão na loja. Realize a conferência.'
                        : 'Confirme a chegada do caminhão para iniciar o recebimento.'}
                  </p>
                </div>

                {departureConfirmed ? (
                  <Badge className="bg-slate-500 text-white px-4 py-2 text-sm flex gap-2">
                    <Truck className="w-4 h-4" /> Caminhão Partiu
                  </Badge>
                ) : arrivalConfirmed ? (
                  <div className="flex items-center gap-3">
                    <Badge className="bg-emerald-500 text-white px-4 py-2 text-sm flex gap-2">
                      <CheckCircle2 className="w-4 h-4" /> Em Andamento
                    </Badge>
                    <Button data-mia-action="confirm-departure"
                      onClick={handleConfirmDeparture}
                      variant={timeLeftToDepart > 0 ? 'outline' : 'destructive'}
                      disabled={timeLeftToDepart > 0}
                      className={
                        timeLeftToDepart > 0
                          ? 'opacity-70 cursor-not-allowed border-slate-300 dark:border-zinc-600'
                          : 'shadow-lg'
                      }
                    >
                      <Truck className="w-4 h-4 mr-2" />
                      {timeLeftToDepart > 0 ? (
                        <span>
                          Aguarde {Math.ceil(timeLeftToDepart / 1000 / 60)}min
                        </span>
                      ) : (
                        'Confirmar Partida'
                      )}
                    </Button>
                  </div>
                ) : (
                  <div className="flex flex-col items-end gap-2">
                    {!isMyTurnToReceive && (
                      <span className="text-xs text-muted-foreground flex items-center gap-1">
                        <Clock className="w-3 h-3" /> Aguardando etapa anterior
                      </span>
