                    <Button data-mia-action="confirm-arrival"
                      onClick={handleConfirmArrival}
                      disabled={!isMyTurnToReceive}
                      className={cn(
                        'transition-all',
                        !isMyTurnToReceive
                          ? 'bg-slate-300 dark:bg-zinc-700 text-slate-500 dark:text-slate-400 cursor-not-allowed'
                          : 'bg-emerald-600 hover:bg-emerald-700 text-white shadow-lg shadow-emerald-500/20',
                      )}
                    >
                      <Truck className="w-4 h-4 mr-2" />
                      Confirmar Chegada
                    </Button>
                  </div>
                )}
              </div>

              {/* RECEPTION / ITEMS LIST */}
              {arrivalConfirmed && !departureConfirmed && (
                <div className="space-y-4">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100 flex items-center gap-2">
                        <Package className="w-5 h-5 text-emerald-600" />
                        Conferência de Itens
                      </h3>
                      <Badge
                        variant="secondary"
                        className="bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400"
                      >
                        {storeItems.filter((i) => i.received).length} /{' '}
                        {storeItems.length}
                      </Badge>
                    </div>
                    <Button
                      onClick={() => setShowScanner(true)}
                      className="bg-slate-900 text-white hover:bg-slate-800 dark:bg-zinc-100 dark:text-zinc-900 dark:hover:bg-zinc-200"
                    >
                      <QrCode className="w-4 h-4 mr-2" />
                      Escanear Etiqueta
                    </Button>
                  </div>

                  {/* Progress Bar */}
                  <div className="h-2 w-full bg-slate-100 dark:bg-zinc-800 rounded-full overflow-hidden">
                    <div
                      className="h-full bg-emerald-500 transition-all duration-500"
                      style={{ width: `${progress}%` }}
                    />
                  </div>

                  <ScrollArea className="h-[300px] bg-white dark:bg-zinc-800/50 rounded-xl border border-slate-200 dark:border-zinc-700 p-4">
                    <div className="space-y-2">
                      {storeItems.map((item) => (
                        <div
                          key={item.id}
                          className={cn(
                            'flex items-center justify-between p-3 rounded-lg border transition-colors',
                            item.received
                              ? 'bg-emerald-50/50 dark:bg-emerald-900/10 border-emerald-200 dark:border-emerald-800/30'
                              : 'bg-white dark:bg-zinc-900 border-slate-100 dark:border-zinc-800 hover:border-emerald-200 dark:hover:border-emerald-700',
                          )}
                        >
                          <div className="flex items-center gap-3">
                            <div
                              className={cn(
                                'w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold',
                                item.received
                                  ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900 dark:text-emerald-400'
                                  : 'bg-slate-100 text-slate-500 dark:bg-zinc-800 dark:text-zinc-400',
                              )}
                            >
                              {item.received ? (
                                <CheckCircle2 className="w-4 h-4" />
                              ) : (
                                item.sent
                              )}
                            </div>
                            <div>
                              <p
                                className={cn(
                                  'font-medium text-sm',
                                  item.received
                                    ? 'text-emerald-900 dark:text-emerald-300'
                                    : 'text-slate-900 dark:text-slate-200',
                                )}
                              >
                                {item.name}
                              </p>
                              <p className="text-xs text-slate-500 dark:text-slate-400">
                                {item.category} • Solicitado: {item.requested}
                              </p>
                            </div>
                          </div>

                          {!item.received && (
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleManualCheck(item)}
                              className="text-slate-400 hover:text-emerald-600 dark:text-slate-500 dark:hover:text-emerald-400"
                            >
                              <CheckSquare className="w-4 h-4" />
                            </Button>
                          )}
                        </div>
                      ))}

                      {storeItems.length === 0 && (
                        <div className="text-center py-10 text-slate-400 dark:text-slate-500 text-sm">
                          Nenhum item encontrado para esta unidade.
                        </div>
                      )}
                    </div>
                  </ScrollArea>
                </div>
              )}
            </div>
          )}
        </div>
      </DialogContent>

      <ReceiptScanner
        isOpen={showScanner}
        onClose={() => setShowScanner(false)}
        onScan={handleScan}
      />
    </Dialog>
  );
}

