1	import { useState, useEffect, useMemo } from "react";
2	import { printHTML } from '@/shared/lib/print';
3	import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/shared/ui/dialog";
4	import { Button } from "@/shared/ui/button";
5	import { Input } from "@/shared/ui/input";
6	import { Label } from "@/shared/ui/label";
7	import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/shared/ui/tabs";
8	import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/shared/ui/card";
9	import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/shared/ui/table";
10	import { Badge } from "@/shared/ui/badge";
11	import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/shared/ui/select";
12	import { TrendingUp, Package, Calendar, Building2, Search, X, ListChecks, FileDown, ArrowUpDown, Printer, Edit3, Plus, Trash2 } from "lucide-react";
13	import { toast } from "sonner";
14	import { supabase } from "@/integrations/supabase/client";
15	import { useIsMobile } from "@/shared/hooks/use-mobile";
16	import { normalizeStoreName, getStoreLabel } from "@/shared/ui/StoreSelector";
17	import { formatDateDDMMYY, coerceISODateString } from "@/shared/lib/utils";
18	import * as XLSX from "xlsx";
19	import { wideError } from '@/shared/lib/telemetry/wide-events';
20	import RequisicaoDetailsModal from "./RequisicaoDetailsModal";
21	
22	interface ReportsModalProps {
23	  isOpen: boolean;
24	  onClose: () => void;
25	}
26	
27	interface EnvioItem {
28	  id: number;
29	  nome_produto: string;
30	  quantidade_solicitada: number;
31	  quantidade_enviada: string;
32	  data_pedido: string;
33	  data_recebimento: string;
34	  loja_solicitante: string;
35	  loja_preparadora: string;
36	  solicitante: string;
37	  nome_requisicao: string;
38	}
39	
40	interface MonthlyStats {
41	  month: string;
42	  count: number;
43	  total_quantidade: number;
44	}
45	
46	interface TopProduct {
47	  nome_produto: string;
48	  total_quantidade: number;
49	  total_envios: number;
50	}
51	
52	interface RequisicaoRow {
53	  id: number;
54	  nome: string;
55	  solicitante: string;
56	  loja_solicitante: string;
57	  loja_preparadora: string;
58	  data_pedido: string; // ISO yyyy-mm-dd
59	  data_recebimento: string | null;
60	  created_at: string;
61	}
62	
63	// Lista de lojas baseada no histórico de requisições para garantir correspondência exata
64	
65	export function ReportsModal({ isOpen, onClose }: ReportsModalProps) {
66	  const isMobile = useIsMobile();
67	  const [loading, setLoading] = useState(false);
68	  const [searchProduct, setSearchProduct] = useState('');
69	  const [searchLoja, setSearchLoja] = useState('');
70	  const [dateStart, setDateStart] = useState('');
71	  const [dateEnd, setDateEnd] = useState('');
72	  const [productResults, setProductResults] = useState<EnvioItem[]>([]);
73	  const [lojaResults, setLojaResults] = useState<EnvioItem[]>([]);
74	  const [monthlyStats, setMonthlyStats] = useState<MonthlyStats[]>([]);
75	  const [topProducts, setTopProducts] = useState<TopProduct[]>([]);
76	  const [lojas, setLojas] = useState<string[]>([]);
77	  const [topProductsStoreFilter, setTopProductsStoreFilter] =
78	    useState<string>('');
79	
80	  // Estado para a aba Listas
81	  const [listasLoading, setListasLoading] = useState(false);
82	  const [listResults, setListResults] = useState<RequisicaoRow[]>([]);
83	  const [searchLojaList, setSearchLojaList] = useState<string>('');
84	  const [searchTermList, setSearchTermList] = useState<string>('');
85	  const [isDetailsOpen, setDetailsOpen] = useState(false);
86	  const [selectedReq, setSelectedReq] = useState<RequisicaoRow | null>(null);
87	  const [statusFilter, setStatusFilter] = useState<'all' | 'received' | 'sent'>(
88	    'all',
89	  );
90	  const [sortAsc, setSortAsc] = useState(false);
91	
92	  // Estado para edição de requisição em modal
93	  const [isEditOpen, setEditOpen] = useState(false);
94	  const [editReq, setEditReq] = useState<RequisicaoRow | null>(null);
95	  const [editOrderDate, setEditOrderDate] = useState<string>('');
96	  const [editSolicitante, setEditSolicitante] = useState<string>('');
97	  const [editLojaValue, setEditLojaValue] = useState<string>('');
98	
99	  const [editItems, setEditItems] = useState<
100	    Array<{
101	      id?: number;
102	      nome_produto: string;
103	      quantidade_solicitada: string;
104	      quantidade_enviada: string;
105	      observacao?: string;
106	      ordem?: number;
107	    }>
108	  >([]);
109	  const [editDeletedItemIds, setEditDeletedItemIds] = useState<number[]>([]);
110	  const [editLoading, setEditLoading] = useState<boolean>(false);
111	
112	  // Removida lógica de correção automática de loja (Lago Sul) conforme orientação
113	
114	  useEffect(() => {
115	    if (isOpen) {
116	      loadMonthlyStats();
117	      loadTopProducts(topProductsStoreFilter || undefined);
118	      loadLojas();
119	      // Carregar listas imediatamente ao abrir o modal (lista completa)
120	      loadListas();
121	    }
122	    // eslint-disable-next-line react-hooks/exhaustive-deps
123	  }, [isOpen, topProductsStoreFilter]);
124	
125	  // Atualizar automaticamente ao alterar filtros, sem precisar clicar em "Buscar"
126	  useEffect(() => {
127	    loadListas();
128	    // eslint-disable-next-line react-hooks/exhaustive-deps
129	  }, [
130	    searchLojaList,
131	    dateStart,
132	    dateEnd,
133	    searchTermList,
134	    statusFilter,
135	    sortAsc,
136	  ]);
137	
138	  const loadLojas = async () => {
139	    try {
140	      // Carregar lojas a partir do histórico de requisições para garantir correspondência exata
141	      const { data, error } = await supabase
142	        .from('requisicoes')
143	        .select('loja_solicitante')
144	        .eq('status', 'finalizada')
145	        .not('loja_solicitante', 'is', null);
146	
147	      if (error) throw error;
148	      const nomes = (data || [])
149	        .map(
150	          (r: any) =>
151	            normalizeStoreName(r.loja_solicitante) || r.loja_solicitante,
152	        )
153	        .filter(Boolean);
154	      const unicos = Array.from(new Set(nomes)).sort((a, b) =>
155	        a.localeCompare(b),
156	      );
157	      setLojas(unicos);
158	    } catch (error) {
159	      wideError('relatorios.carregar_lojas', 'Falha ao carregar lojas', { attributes: { 'operation.name': 'loadLojas', 'error.message': String(error) } });
160	    }
161	  };
162	
163	  const searchByProduct = async () => {
164	    // Se não há produto nem datas específicas, buscar todos os itens
165	    if (!searchProduct.trim() && !dateStart && !dateEnd) {
166	      // Permitir busca de todos os itens
167	    } else if (!searchProduct.trim()) {
168	      toast.error(
169	        'Digite o nome do produto para buscar ou deixe as datas vazias para ver todos os itens',
170	      );
171	      return;
172	    }
173	
174	    setLoading(true);
175	    try {
176	      let query = supabase.from('requisicoes_itens').select(`
177	          *,
178	          requisicoes!inner(data_pedido, nome, solicitante, loja_solicitante)
179	        `);
180	      // Apenas listas aprovadas
181	      query = query.eq('requisicoes.status', 'finalizada');
182	
183	      // Aplicar filtro de produto apenas se especificado
184	      if (searchProduct.trim()) {
185	        query = query.ilike('nome_produto', `%${searchProduct}%`);
186	      }
187	
188	      if (dateStart) {
189	        query = query.gte('requisicoes.data_pedido', dateStart);
190	      }
191	      if (dateEnd) {
192	        query = query.lte('requisicoes.data_pedido', dateEnd);
193	      }
194	
195	      const { data, error } = await query;
196	
197	      if (error) throw error;
198	
199	      // Transformar os dados para mostrar quantidade correta
200	      const transformedData: EnvioItem[] = data?.map((item) => ({
201	        ...item,
202	        data_pedido: item.requisicoes.data_pedido,
203	        nome_requisicao: item.requisicoes.nome,
204	        solicitante: item.requisicoes.solicitante,
205	        loja_solicitante: normalizeStoreName(item.requisicoes.loja_solicitante || '') || (item.requisicoes.loja_solicitante || ''),
206	        loja_preparadora: (item as any).loja_preparadora || '',
207	        data_recebimento: (item as any).data_recebimento || '',
208	        // Se quantidade_enviada estiver vazia, usa quantidade_solicitada
209	        quantidade_enviada: item.quantidade_enviada || item.quantidade_solicitada?.toString() || '0'
210	      })) || [];
211	
212	      // Ordenar por data_pedido após a transformação
213	      transformedData.sort(
214	        (a, b) =>
215	          new Date(b.data_pedido).getTime() - new Date(a.data_pedido).getTime(),
216	      );
217	
218	      setProductResults(transformedData);
219	    } catch (error) {
220	      wideError('relatorios.busca_produto', 'Falha na busca por produto', { attributes: { 'operation.name': 'searchByProduct', 'error.message': String(error) } });
221	      toast.error('Erro ao buscar produto');
222	    } finally {
223	      setLoading(false);
224	    }
225	  };
226	
227	  const searchByLoja = async () => {
228	    if (!searchLoja.trim()) {
229	      toast.error('Selecione uma loja para buscar');
230	      return;
231	    }
232	
233	    setLoading(true);
234	    try {
235	      const lojaLabel = getStoreLabel(searchLoja);
236	      let query = supabase
237	        .from('requisicoes')
238	        .select(
239	          `
240	          *,
241	          requisicoes_itens(
242	            nome_produto,
243	            quantidade_solicitada,
244	            quantidade_enviada
245	          )
246	        `,
247	        )
248	        // Buscar pela loja normalizada como solicitante OU preparadora
249	        .or(
250	          `loja_solicitante.eq.${lojaLabel},` +
251	            `loja_preparadora.eq.${lojaLabel}`,
252	        );
253	      // Apenas listas aprovadas
254	      query = query.eq('status', 'finalizada');
255	
256	      if (dateStart) {
257	        query = query.gte('data_pedido', dateStart);
258	      }
259	      if (dateEnd) {
260	        query = query.lte('data_pedido', dateEnd);
261	      }
262	
263	      const { data, error } = await query.order('data_pedido', {
264	        ascending: false,
265	      });
266	
267	      if (error) throw error;
268	
269	      // Transformar os dados para o formato esperado
270	      const transformedData: EnvioItem[] = [];
271	      data?.forEach((requisicao) => {
272	        requisicao.requisicoes_itens?.forEach((item: any, index: number) => {
273	          transformedData.push({
274	            id: `${requisicao.id}-${index}` as any,
275	            nome_produto: item.nome_produto,
