import { useState, useEffect, useMemo } from "react";
import { printHTML } from '@/shared/lib/print';
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/shared/ui/dialog";
import { Button } from "@/shared/ui/button";
import { Input } from "@/shared/ui/input";
import { Label } from "@/shared/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/shared/ui/tabs";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/shared/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/shared/ui/table";
import { Badge } from "@/shared/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/shared/ui/select";
import { TrendingUp, Package, Calendar, Building2, Search, X, ListChecks, FileDown, ArrowUpDown, Printer, Edit3, Plus, Trash2 } from "lucide-react";
import { toast } from "sonner";
import { supabase } from "@/integrations/supabase/client";
import { useIsMobile } from "@/shared/hooks/use-mobile";
import { normalizeStoreName, getStoreLabel } from "@/shared/ui/StoreSelector";
import { formatDateDDMMYY, coerceISODateString } from "@/shared/lib/utils";
import * as XLSX from "xlsx";
import { wideError } from '@/shared/lib/telemetry/wide-events';
import RequisicaoDetailsModal from "./RequisicaoDetailsModal";

interface ReportsModalProps {
  isOpen: boolean;
  onClose: () => void;
}

interface EnvioItem {
  id: number;
  nome_produto: string;
  quantidade_solicitada: number;
  quantidade_enviada: string;
  data_pedido: string;
  data_recebimento: string;
  loja_solicitante: string;
  loja_preparadora: string;
  solicitante: string;
  nome_requisicao: string;
}

interface MonthlyStats {
  month: string;
  count: number;
  total_quantidade: number;
}

interface TopProduct {
  nome_produto: string;
  total_quantidade: number;
  total_envios: number;
}

interface RequisicaoRow {
  id: number;
  nome: string;
  solicitante: string;
  loja_solicitante: string;
  loja_preparadora: string;
  data_pedido: string; // ISO yyyy-mm-dd
  data_recebimento: string | null;
  created_at: string;
}

// Lista de lojas baseada no histórico de requisições para garantir correspondência exata

export function ReportsModal({ isOpen, onClose }: ReportsModalProps) {
  const isMobile = useIsMobile();
  const [loading, setLoading] = useState(false);
  const [searchProduct, setSearchProduct] = useState('');
  const [searchLoja, setSearchLoja] = useState('');
  const [dateStart, setDateStart] = useState('');
  const [dateEnd, setDateEnd] = useState('');
  const [productResults, setProductResults] = useState<EnvioItem[]>([]);
  const [lojaResults, setLojaResults] = useState<EnvioItem[]>([]);
  const [monthlyStats, setMonthlyStats] = useState<MonthlyStats[]>([]);
  const [topProducts, setTopProducts] = useState<TopProduct[]>([]);
  const [lojas, setLojas] = useState<string[]>([]);
  const [topProductsStoreFilter, setTopProductsStoreFilter] =
    useState<string>('');

  // Estado para a aba Listas
  const [listasLoading, setListasLoading] = useState(false);
  const [listResults, setListResults] = useState<RequisicaoRow[]>([]);
  const [searchLojaList, setSearchLojaList] = useState<string>('');
  const [searchTermList, setSearchTermList] = useState<string>('');
  const [isDetailsOpen, setDetailsOpen] = useState(false);
  const [selectedReq, setSelectedReq] = useState<RequisicaoRow | null>(null);
  const [statusFilter, setStatusFilter] = useState<'all' | 'received' | 'sent'>(
    'all',
  );
  const [sortAsc, setSortAsc] = useState(false);

  // Estado para edição de requisição em modal
  const [isEditOpen, setEditOpen] = useState(false);
  const [editReq, setEditReq] = useState<RequisicaoRow | null>(null);
  const [editOrderDate, setEditOrderDate] = useState<string>('');
  const [editSolicitante, setEditSolicitante] = useState<string>('');
  const [editLojaValue, setEditLojaValue] = useState<string>('');

  const [editItems, setEditItems] = useState<
    Array<{
      id?: number;
      nome_produto: string;
      quantidade_solicitada: string;
      quantidade_enviada: string;
      observacao?: string;
      ordem?: number;
    }>
  >([]);
  const [editDeletedItemIds, setEditDeletedItemIds] = useState<number[]>([]);
  const [editLoading, setEditLoading] = useState<boolean>(false);

  // Removida lógica de correção automática de loja (Lago Sul) conforme orientação

  useEffect(() => {
    if (isOpen) {
      loadMonthlyStats();
      loadTopProducts(topProductsStoreFilter || undefined);
      loadLojas();
      // Carregar listas imediatamente ao abrir o modal (lista completa)
      loadListas();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen, topProductsStoreFilter]);

  // Atualizar automaticamente ao alterar filtros, sem precisar clicar em "Buscar"
  useEffect(() => {
    loadListas();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    searchLojaList,
    dateStart,
    dateEnd,
    searchTermList,
    statusFilter,
    sortAsc,
  ]);

  const loadLojas = async () => {
    try {
      // Carregar lojas a partir do histórico de requisições para garantir correspondência exata
      const { data, error } = await supabase
        .from('requisicoes')
        .select('loja_solicitante')
        .eq('status', 'finalizada')
        .not('loja_solicitante', 'is', null);

      if (error) throw error;
      const nomes = (data || [])
        .map(
          (r: any) =>
            normalizeStoreName(r.loja_solicitante) || r.loja_solicitante,
        )
        .filter(Boolean);
      const unicos = Array.from(new Set(nomes)).sort((a, b) =>
        a.localeCompare(b),
      );
      setLojas(unicos);
    } catch (error) {
      wideError('relatorios.carregar_lojas', 'Falha ao carregar lojas', { attributes: { 'operation.name': 'loadLojas', 'error.message': String(error) } });
    }
  };

  const searchByProduct = async () => {
    // Se não há produto nem datas específicas, buscar todos os itens
    if (!searchProduct.trim() && !dateStart && !dateEnd) {
      // Permitir busca de todos os itens
    } else if (!searchProduct.trim()) {
      toast.error(
        'Digite o nome do produto para buscar ou deixe as datas vazias para ver todos os itens',
      );
      return;
    }

    setLoading(true);
    try {
      let query = supabase.from('requisicoes_itens').select(`
          *,
          requisicoes!inner(data_pedido, nome, solicitante, loja_solicitante)
        `);
      // Apenas listas aprovadas
      query = query.eq('requisicoes.status', 'finalizada');

      // Aplicar filtro de produto apenas se especificado
      if (searchProduct.trim()) {
        query = query.ilike('nome_produto', `%${searchProduct}%`);
      }

      if (dateStart) {
        query = query.gte('requisicoes.data_pedido', dateStart);
      }
      if (dateEnd) {
        query = query.lte('requisicoes.data_pedido', dateEnd);
      }

      const { data, error } = await query;

      if (error) throw error;

      // Transformar os dados para mostrar quantidade correta
      const transformedData: EnvioItem[] = data?.map((item) => ({
        ...item,
        data_pedido: item.requisicoes.data_pedido,
        nome_requisicao: item.requisicoes.nome,
        solicitante: item.requisicoes.solicitante,
        loja_solicitante: normalizeStoreName(item.requisicoes.loja_solicitante || '') || (item.requisicoes.loja_solicitante || ''),
        loja_preparadora: (item as any).loja_preparadora || '',
        data_recebimento: (item as any).data_recebimento || '',
        // Se quantidade_enviada estiver vazia, usa quantidade_solicitada
        quantidade_enviada: item.quantidade_enviada || item.quantidade_solicitada?.toString() || '0'
      })) || [];

      // Ordenar por data_pedido após a transformação
      transformedData.sort(
        (a, b) =>
          new Date(b.data_pedido).getTime() - new Date(a.data_pedido).getTime(),
      );

      setProductResults(transformedData);
    } catch (error) {
      wideError('relatorios.busca_produto', 'Falha na busca por produto', { attributes: { 'operation.name': 'searchByProduct', 'error.message': String(error) } });
      toast.error('Erro ao buscar produto');
    } finally {
      setLoading(false);
    }
  };

  const searchByLoja = async () => {
    if (!searchLoja.trim()) {
      toast.error('Selecione uma loja para buscar');
      return;
    }

    setLoading(true);
    try {
      const lojaLabel = getStoreLabel(searchLoja);
      let query = supabase
        .from('requisicoes')
        .select(
          `
          *,
          requisicoes_itens(
            nome_produto,
            quantidade_solicitada,
            quantidade_enviada
          )
        `,
        )
        // Buscar pela loja normalizada como solicitante OU preparadora
        .or(
          `loja_solicitante.eq.${lojaLabel},` +
            `loja_preparadora.eq.${lojaLabel}`,
        );
      // Apenas listas aprovadas
      query = query.eq('status', 'finalizada');

      if (dateStart) {
        query = query.gte('data_pedido', dateStart);
      }
      if (dateEnd) {
        query = query.lte('data_pedido', dateEnd);
      }

      const { data, error } = await query.order('data_pedido', {
        ascending: false,
      });

      if (error) throw error;

      // Transformar os dados para o formato esperado
      const transformedData: EnvioItem[] = [];
      data?.forEach((requisicao) => {
        requisicao.requisicoes_itens?.forEach((item: any, index: number) => {
          transformedData.push({
            id: `${requisicao.id}-${index}` as any,
            nome_produto: item.nome_produto,
            quantidade_solicitada: item.quantidade_solicitada,
            quantidade_enviada:
              item.quantidade_enviada || item.quantidade_solicitada || '0',
            data_pedido: requisicao.data_pedido,
            data_recebimento: requisicao.data_recebimento || '',
            loja_solicitante: requisicao.loja_solicitante || '',
            loja_preparadora: requisicao.loja_preparadora || '',
            solicitante: requisicao.solicitante,
            nome_requisicao: requisicao.nome,
          });
        });
      });

      setLojaResults(transformedData);
    } catch (error) {
      wideError('relatorios.busca_loja', 'Falha na busca por loja', { attributes: { 'operation.name': 'searchByLoja', 'error.message': String(error) } });
      toast.error('Erro ao buscar por loja');
    } finally {
      setLoading(false);
    }
  };

