import { cn } from '@/shared/lib/utils';
import { Stop } from '@/shared/types/logistics';
import {
  Check,
  ClipboardList,
  Package,
  BoxSelect,
  Store,
  Truck,
} from 'lucide-react';

interface MetroLineNodeProps {
  stop: Stop;
  isLast: boolean;
  isFirst: boolean;
}

export function MetroLineNode({ stop, isLast, isFirst }: MetroLineNodeProps) {
  const isCompleted = stop.status === 'completed';
  const isCurrent = stop.status === 'current';
  const isPending = stop.status === 'pending' || stop.status === 'next';
  const isProcess = stop.type === 'process';

  // --- COLOR PALETTE ---
  const completedColor = 'bg-emerald-500';
  const currentColor = 'bg-amber-400';
  const pendingColor = 'bg-slate-200';
  const pendingTextColor = 'text-slate-400';

  // --- GLOWS ---
  const completedGlow = 'shadow-[0_0_15px_rgba(16,185,129,0.5)]';
  const currentGlow = 'shadow-[0_0_20px_rgba(251,191,36,0.6)]';

  // Get the right icon for this stop
  const getIcon = () => {
    const iconClasses = cn(
      isProcess ? 'w-5 h-5' : 'w-6 h-6',
      isCompleted ? 'text-white' : isCurrent ? 'text-white' : pendingTextColor,
    );

    if (isCompleted) return <Check className={cn(iconClasses, 'stroke-[3]')} />;
    if (stop.name.includes('Separação'))
      return <ClipboardList className={iconClasses} />;
    if (stop.name.includes('Carregamento'))
      return <Package className={iconClasses} />;
    if (stop.name.includes('Conf') || stop.name.includes('Despacho'))
      return <Truck className={iconClasses} />;
    if (stop.type === 'process') return <BoxSelect className={iconClasses} />;
    return <Store className={iconClasses} />;
  };

  return (
    <div
      className={cn(
        'flex flex-col items-center flex-1 group',
        isProcess ? 'min-w-[140px]' : 'min-w-[120px]',
      )}
    >
      {/* --- LINE & NODE ROW --- */}
      <div className="relative w-full h-16 flex items-center justify-center">
        {/* === LEFT CONNECTING LINE === */}
        {!isFirst && (
          <div
            className="absolute top-1/2 -translate-y-1/2 h-[4px] bg-slate-200 overflow-hidden"
            style={{ right: '50%', width: 'calc(50% + 8px)' }}
          >
            {/* Progress fill overlay */}
            <div
              className={cn(
                'h-full w-full transition-all duration-700 ease-out',
                isCompleted || isCurrent ? completedColor : 'w-0',
              )}
            />
          </div>
        )}

        {/* === RIGHT CONNECTING LINE === */}
        {!isLast && (
          <div
            className="absolute top-1/2 -translate-y-1/2 h-[4px] bg-slate-200 overflow-hidden"
            style={{ left: '50%', width: 'calc(50% + 8px)' }}
          >
            {/* Progress fill overlay */}
            <div
              className={cn(
                'h-full transition-all duration-700 ease-out',
                isCompleted ? cn('w-full', completedColor) : 'w-0',
              )}
            />
          </div>
        )}

        {/* === THE NODE CIRCLE === */}
        <div
          className={cn(
            'relative z-10 flex items-center justify-center rounded-full transition-all duration-500 border-4 border-white dark:border-zinc-900',
            isProcess ? 'w-12 h-12' : 'w-14 h-14',
            isCompleted
              ? cn(completedColor, completedGlow)
              : isCurrent
                ? cn(currentColor, currentGlow, 'scale-110 animate-pulse')
                : cn(
                    'bg-white dark:bg-zinc-800',
                    'border-slate-200 dark:border-zinc-700',
                  ),
          )}
        >
          {getIcon()}
        </div>
      </div>

      {/* --- LABEL BELOW NODE --- */}
      <div className="flex flex-col items-center mt-1 text-center px-1">
        <span
          className={cn(
            'font-semibold text-xs transition-all duration-300 leading-tight',
            isCompleted
              ? 'text-emerald-700 dark:text-emerald-400'
              : isCurrent
                ? 'text-amber-600 dark:text-amber-400 font-bold'
                : 'text-slate-400 dark:text-slate-500',
          )}
        >
          {stop.name}
        </span>

        {/* TIMESTAMP INFO - Arrival/Departure Times */}
        {(stop.arrivalTime || stop.departureTime) && (
          <div className="mt-1 space-y-0.5 text-[9px] font-medium">
            {stop.arrivalTime && (
              <div className="flex items-center gap-1 text-emerald-600 dark:text-emerald-400">
                <span>⏵</span>
                <span>
                  Chegou:{' '}
                  {new Date(stop.arrivalTime).toLocaleTimeString('pt-BR', {
                    hour: '2-digit',
                    minute: '2-digit',
                  })}
                </span>
              </div>
            )}
            {stop.departureTime && (
              <div className="flex items-center gap-1 text-slate-500 dark:text-slate-400">
                <span>⏸</span>
                <span>
                  Partiu:{' '}
                  {new Date(stop.departureTime).toLocaleTimeString('pt-BR', {
                    hour: '2-digit',
                    minute: '2-digit',
                  })}
                </span>
              </div>
            )}
          </div>
        )}

        {/* CURRENT BADGE */}
        {isCurrent && (
          <div className="mt-1.5 flex items-center gap-1 px-2 py-0.5 rounded-full bg-amber-100 dark:bg-amber-900/30 border border-amber-200 dark:border-amber-700/50">
            <span className="relative flex h-1.5 w-1.5">
              <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-amber-400 opacity-75" />
              <span className="relative inline-flex rounded-full h-1.5 w-1.5 bg-amber-500" />
            </span>
            <span className="text-[9px] font-bold text-amber-700 dark:text-amber-400 uppercase tracking-wider">
              Agora
            </span>
          </div>
        )}

        {/* SUB-STEPS for separation/loading */}
        {stop.subSteps && stop.subSteps.length > 0 && (
          <div className="mt-2 space-y-1 w-full max-w-[130px]">
            {stop.subSteps.map((sub) => (
              <div
                key={sub.id}
                className={cn(
                  'flex items-center justify-between px-2 py-1 rounded-md border text-[9px] font-medium transition-all',
                  sub.status === 'completed'
                    ? 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-200 dark:border-emerald-800 text-emerald-700 dark:text-emerald-400'
                    : sub.status === 'in_progress'
                      ? 'bg-amber-50 dark:bg-amber-900/20 border-amber-200 dark:border-amber-800 text-amber-700 dark:text-amber-400'
                      : 'bg-white dark:bg-zinc-800 border-slate-100 dark:border-zinc-700 text-slate-400 dark:text-slate-500',
                )}
              >
                <span className="truncate flex-1" title={sub.label}>
                  {sub.label}
                </span>
                {sub.status === 'completed' && (
                  <Check className="w-2.5 h-2.5 text-emerald-500 ml-1 flex-shrink-0" />
                )}
                {sub.status === 'in_progress' && (
                  <div className="w-2 h-2 rounded-full bg-amber-400 ml-1 animate-pulse shadow-[0_0_6px_rgba(251,191,36,0.6)] flex-shrink-0" />
                )}
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

