-- Criar tabela para itens da pipeline baseados na requisição
CREATE TABLE public.pipeline_itens (
    id BIGSERIAL PRIMARY KEY,
    pipeline_id BIGINT NOT NULL REFERENCES public.requisition_pipelines(id) ON DELETE CASCADE,
    nome_produto TEXT NOT NULL,
    quantidade_solicitada INTEGER NOT NULL DEFAULT 0,
    quantidade_enviada INTEGER NOT NULL DEFAULT 0,
    quantidade_separada INTEGER DEFAULT 0,
    observacao TEXT,
    ordem INTEGER NOT NULL DEFAULT 0,
    status TEXT DEFAULT 'pendente' CHECK (status IN ('pendente', 'separando', 'separado', 'carregado', 'entregue')),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Adicionar índices para melhor performance
CREATE INDEX idx_pipeline_itens_pipeline_id ON public.pipeline_itens(pipeline_id);
CREATE INDEX idx_pipeline_itens_status ON public.pipeline_itens(status);
CREATE INDEX idx_pipeline_itens_ordem ON public.pipeline_itens(pipeline_id, ordem);

-- Adicionar RLS (Row Level Security)
ALTER TABLE public.pipeline_itens ENABLE ROW LEVEL SECURITY;

-- Política para permitir acesso aos usuários autenticados
CREATE POLICY "Usuários autenticados podem ver itens da pipeline" ON public.pipeline_itens
    FOR SELECT USING (auth.role() = 'authenticated');

CREATE POLICY "Usuários autenticados podem inserir itens da pipeline" ON public.pipeline_itens
    FOR INSERT WITH CHECK (auth.role() = 'authenticated');

CREATE POLICY "Usuários autenticados podem atualizar itens da pipeline" ON public.pipeline_itens
    FOR UPDATE USING (auth.role() = 'authenticated');

CREATE POLICY "Usuários autenticados podem deletar itens da pipeline" ON public.pipeline_itens
    FOR DELETE USING (auth.role() = 'authenticated');

-- Comentários explicativos
COMMENT ON TABLE public.pipeline_itens IS 'Itens da requisição associados a uma pipeline';
COMMENT ON COLUMN public.pipeline_itens.pipeline_id IS 'ID da pipeline à qual o item pertence';
COMMENT ON COLUMN public.pipeline_itens.nome_produto IS 'Nome do produto';
COMMENT ON COLUMN public.pipeline_itens.quantidade_solicitada IS 'Quantidade solicitada na requisição';
COMMENT ON COLUMN public.pipeline_itens.quantidade_enviada IS 'Quantidade que deve ser enviada';
COMMENT ON COLUMN public.pipeline_itens.quantidade_separada IS 'Quantidade efetivamente separada';
COMMENT ON COLUMN public.pipeline_itens.status IS 'Status do item na pipeline: pendente, separando, separado, carregado, entregue';
COMMENT ON COLUMN public.pipeline_itens.ordem IS 'Ordem do item na lista original da requisição';

